    assert not violations, "valid allocation reported violations:\n" + \
        "\n".join(violations)
    print("verify: OK")

    # The allocator must have made a spill decision somewhere (loop pressure
    # plus a single callee-saved register cannot hold every live value).
    assert result.spilled, "expected at least one spill"
    # Rematerialization must have been used for at least one constant.
    assert any(v in remat_candidates(func) for v in result.spilled), \
        "expected a rematerialized constant"

    # Strongest check: execute the original virtual-register program and the
    # allocated/spilled physical-register program and compare return values.
    expected = execute(func)
