    assert not violations2, "\n".join(violations2)
    # y was coalesced into x, so x must be in r1 (fixed use of a0? a0 is r1)
    assert result2.alloc["a0"] == "r1", result2.alloc
    assert result2.alloc["r"] == "r2", result2.alloc
    assert "fc" in result2.alloc and result2.alloc["fc"] in ("f0", "f1")
    print("verify: OK")

    print()
