    tests = [v for k, v in sorted(globals().items()) if k.startswith("test_")]
    for t in tests:
        t()
        print(f"PASS {t.__name__}")
    print(f"\n{len(tests)} tests passed")


def _build_diamond_function(nregs=2):
    m = Machine()
    m.add_class("gp", [f"r{i}" for i in range(nregs)])
    cls = {v: "gp" for v in ["v0", "v1", "va", "vb", "v3", "v4", "cond"]}
    return Function("diamond", [
        Block("entry", [
            Instr("const", defs=["v0"], imm=3, remat=True),
            Instr("const", defs=["v1"], imm=4, remat=True),
            Instr("const", defs=["va"], imm=0),
            Instr("const", defs=["vb"], imm=0),
            Instr("const", defs=["cond"], imm=1),
            Instr("br", uses=["cond"], is_branch=True),
        ], ["then", "else"]),
        Block("then", [
            Instr("add", defs=["va"], uses=["v0", "v1"]),
            Instr("jmp", is_branch=True),
        ], ["merge"]),
        Block("else", [
            Instr("sub", defs=["vb"], uses=["v0", "v1"]),
            Instr("jmp", is_branch=True),
        ], ["merge"]),
        Block("merge", [
            Instr("add", defs=["v3"], uses=["va", "vb"]),
            Instr("add", defs=["v4"], uses=["v3", "v0"]),
            Instr("ret", uses=["v4"]),
        ], []),
    ], m, cls, "entry")


def test_diamond_split_live_range_semantics():
    func = _build_diamond_function(nregs=2)
    res = allocate_function(func)
    assert not verify(res.func, func.machine, res.alloc, res.spilled,
                      res.slots, res.live, res.adj)
    assert execute(func) == execute(res.func) == 10


def test_diamond_three_registers_semantics():
    func = _build_diamond_function(nregs=3)
    res = allocate_function(func)
    assert not verify(res.func, func.machine, res.alloc, res.spilled,
